import {blockFrame,defeatFrame} from './defense.js';
import {loadDiddyAssets} from './diddy.js?v=2';
const $=id=>document.getElementById(id),cache=new Map();
let roster=[],atlas={},selected=0,active=null,token=0,last=0,elapsed=0,tourAge=0,face=1,playing=!matchMedia('(prefers-reduced-motion: reduce)').matches;
function image(src){if(!cache.has(src))cache.set(src,new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('Unable to load '+src));im.src=new URL(src,import.meta.url).href;}));return cache.get(src);}
async function pose(key,index){if(key==='diddy'&&!atlas.diddy)atlas.diddy=await loadDiddyAssets(import.meta.url);const e=atlas[key];if(!e)throw Error('Missing sprite '+key);if(!e.image)e.image=await image(e.src);const f=e.frames[index];if(!f)throw Error('Missing pose '+key+':'+index);return {e,f,img:f.src?await image(f.src):e.image};}
function paint(id,p){const c=$(id),g=c.getContext('2d');g.clearRect(0,0,c.width,c.height);if(!p)return;const {e,f,img}=p,scale=260/(e.referenceHeight||e.frames[0].h);g.save();g.translate(250,368);g.scale(face,1);g.imageSmoothingEnabled=true;g.imageSmoothingQuality='high';g.drawImage(img,f.x,f.y,f.w,f.h,-f.anchorX*scale,-f.anchorY*scale,f.w*scale,f.h*scale);g.restore();}
function render(){if(!active)return;const t=elapsed%3.2,i=blockFrame(t,t-.8),k=defeatFrame(Math.max(0,t-.55))-4;paint('block',active.guards[Math.min(i,active.guards.length-1)]);paint('defeat',active.defeats[Math.min(k,active.defeats.length-1)]);$('blockLabel').textContent=active.newGuard?['Raise guard','Hold guard','Block recoil','Recover guard'][i]:'Existing drawn guard';$('defeatLabel').textContent=active.newDefeat?['Knees buckle','Knee drop','Fall to side','Rest on the ground'][k]:'Existing drawn defeat retained';}
async function choose(n){const request=++token;selected=(n+roster.length)%roster.length;const f=roster[selected];$('fighter').value=f.id;$('name').textContent=f.name;$('count').textContent=`${selected+1} / ${roster.length}`;$('status').textContent='Loading poses…';active=null;elapsed=tourAge=0;try{const guards=f.guardSource==='new'?await Promise.all([0,1,2,3].map(i=>pose(f.id+'Defense',i))):await Promise.all((f.id==='diddy'?[51,52]:[7]).map(i=>pose(f.id,i)));const defeats=f.defeatSource==='new'?await Promise.all([4,5,6,7].map(i=>pose(f.id+'Defense',i))):[await pose(f.existingDefeat.key,f.existingDefeat.index)];if(request!==token)return;active={guards,defeats,newGuard:f.guardSource==='new',newDefeat:f.defeatSource==='new'};$('status').textContent='';render();}catch(error){if(request===token)$('status').textContent=error.message;}}
$('prev').onclick=()=>choose(selected-1);$('next').onclick=()=>choose(selected+1);$('fighter').onchange=()=>choose(roster.findIndex(f=>f.id===$('fighter').value));$('pause').onclick=()=>{playing=!playing;$('pause').textContent=playing?'Pause':'Play';};$('replay').onclick=()=>{elapsed=0;playing=true;$('pause').textContent='Pause';render();};$('mirror').onclick=()=>{face=-face;$('mirror').textContent=face<0?'Face right':'Face left';render();};
function loop(now){const dt=Math.min(.06,(now-last)/1000||0);last=now;if(playing){elapsed+=dt*($('slow').checked?.5:1);tourAge+=dt;render();if($('tour').checked&&tourAge>4.5)choose(selected+1);}requestAnimationFrame(loop);}
try{const read=async p=>{const r=await fetch(new URL(p,import.meta.url));if(!r.ok)throw Error('Unable to load sprite catalog');return r.json();};const [r,a,b]=await Promise.all([read('./assets/defense/roster.json'),read('./assets/defense/atlas.json'),read('./assets/atlas.json')]);roster=r;atlas={...b,...a};$('fighter').replaceChildren(...r.map(f=>{const o=document.createElement('option');o.value=f.id;o.textContent=f.name;return o;}));$('pause').textContent=playing?'Pause':'Play';await choose(0);requestAnimationFrame(loop);}catch(error){$('status').textContent=error.message;}
